def histogram(test):
    counts = {}
    for char in test.split():
        counts[char] = counts.get(char, 0) + 1
    if not counts:
        return {}
    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

def reverse_delete(s, c):
    result = ''.join(char for char in s if char not in c)
    return result, result == result[::-1]

import math

def max_fill(grid, capacity):
    return sum(math.ceil(sum(row) / capacity) for row in grid)

def prod_signs(arr):
    if not arr:
        return None
    sum_mag = sum(abs(x) for x in arr)
    prod_sig = 1
    for x in arr:
        if x < 0:
            prod_sig *= -1
        elif x == 0:
            prod_sig = 0
            break
    return sum_mag * prod_sig

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def digits(n):
    product = 1
    found_odd = False
    for d in str(n):
        digit = int(d)
        if digit % 2 != 0:
            product *= digit
            found_odd = True
    return product if found_odd else 0

def can_arrange(arr):
    for i in range(len(arr) - 1, 0, -1):
        if arr[i] < arr[i-1]:
            return i
    return -1

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    return " ".join(word for word in sentence.split() if is_prime(len(word)))

def sorted_list_sum(lst):
    filtered = [s for s in lst if len(s) % 2 == 0]
    return sorted(filtered, key=lambda x: (len(x), x))

def do_algebra(operator, operand):
    expression = str(operand[0])
    for op, num in zip(operator, operand[1:]):
        expression += f" {op} {num}"
    return eval(expression)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

import re

def fruit_distribution(s, n):
    return n - sum(map(int, re.findall(r'\d+', s)))

def triangle_area(a, b, c):
    if a + b > c and a + c > b and b + c > a:
        s = (a + b + c) / 2
        area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
        return round(area, 2)
    return -1

def check_dict_case(dict):
    if not dict:
        return False
    return all(isinstance(k, str) and k.islower() for k in dict) or all(isinstance(k, str) and k.isupper() for k in dict)

def closest_integer(value):
    num = float(value)
    if num >= 0:
        return int(num + 0.5)
    else:
        return int(num - 0.5)
